import fs from 'fs/promises';
import path from 'path';
import { collectSSGAssets, collectStaticAssets, collectStaticMetadataAssets } from './asset-collection.js';
import { buildLambdaZip } from './build-lambda-zip.js';
import { resolveOutputPath } from './deploy-output/resolveOutputPath.js';
import { collectFilesRecursive } from './fs-utils.js';
import { isPublishableAsset } from './secret-files.js';
export class NextjsAdapter {
    logger;
    name = 'nextjs';
    constructor(options = {}){
        this.logger = options.logger;
    }
    async collectAssets(projectPath, output) {
        // Bundle assets: .next/static/ → _next/static/
        const staticAssets = (await collectStaticAssets(projectPath, output, this.logger)).filter(isPublishableAsset);
        const outputPath = resolveOutputPath(projectPath, 'nextjs', output);
        // A normal Next build keeps public/ beside .next. A prebuilt artifact can
        // instead include it in the supplied output directory, which is necessary
        // when the artifact is isolated from the source project (for example Bazel).
        const artifactPublicDir = path.join(outputPath, 'public');
        const publicDir = await fs.stat(artifactPublicDir).then((stat)=>stat.isDirectory()).catch(()=>false) ? artifactPublicDir : path.join(projectPath, 'public');
        let publicAssets = [];
        try {
            await fs.stat(publicDir);
            publicAssets = (await collectFilesRecursive(publicDir, publicDir)).filter(isPublishableAsset);
        } catch  {
        // No public directory
        }
        const metadataAssets = await collectStaticMetadataAssets(projectPath, output);
        const pathMap = {};
        for (const key of staticAssets){
            pathMap[key] = path.relative(projectPath, path.join(outputPath, key.replace(/^_next\//, '')));
        }
        for (const key of publicAssets){
            pathMap[key] = path.relative(projectPath, path.join(publicDir, key));
        }
        for (const key of metadataAssets.keys.filter(isPublishableAsset)){
            pathMap[key] = metadataAssets.pathMap[key];
        }
        const uploadKeys = Object.keys(pathMap);
        return {
            pathMap,
            routes: uploadKeys.map((key)=>`/${key}`),
            uploadKeys
        };
    }
    async collectPages(projectPath, output) {
        const ssg = await collectSSGAssets(projectPath, output, this.logger);
        // collectSSGAssets records each key's manifest route while scanning the
        // output, preserving the existing mapping for HTML/RSC/meta files while
        // supporting segment keys whose nested names do not encode the page route.
        return {
            pathMap: ssg.pathMap,
            routeAssetMap: ssg.routeAssetMap,
            routes: Object.keys(ssg.routeAssetMap),
            uploadKeys: ssg.keys
        };
    }
    async prepareLambdaBundle(projectPath, output, options) {
        return buildLambdaZip(projectPath, output, {
            ...options,
            logger: this.logger
        });
    }
}
export const nextjsAdapter = new NextjsAdapter();
